# Wipe all tables and reload the sample data (handy before a demo or a Postman run)
# Run:  powershell -ExecutionPolicy Bypass -File .\reset-db.ps1

Set-Location $PSScriptRoot
$env:DISABLE_SQLALCHEMY_CEXT_RUNTIME = "1"
$py = ".\.venv\Scripts\python.exe"
if (-not (Test-Path $py)) { Write-Host "Run setup.ps1 first" -ForegroundColor Red; exit 1 }

$answer = Read-Host "This deletes ALL data in the database. Type YES to continue"
if ($answer -ne "YES") { Write-Host "Cancelled"; exit 0 }

# drop every table (plus alembic's version table) instead of "alembic downgrade base",
# because autogenerated downgrades can trip over foreign key indexes on MySQL
& $py -c "from sqlalchemy import text; from app.database import Base, engine; import app.models; Base.metadata.drop_all(engine); c = engine.connect(); c.execute(text('DROP TABLE IF EXISTS alembic_version')); c.commit(); c.close(); print('[OK] tables dropped')"
if ($LASTEXITCODE -ne 0) { Write-Host "Could not drop tables" -ForegroundColor Red; exit 1 }

& $py -m alembic upgrade head
if ($LASTEXITCODE -ne 0) { Write-Host "Migration failed" -ForegroundColor Red; exit 1 }

& $py seed.py
Write-Host "Database reset done" -ForegroundColor Green